(async () => {
  const { env } = await import('node:process');
  if (!env.YAML_TEXT) throw new Error('Missing required env var YAML_TEXT');
  globalThis.yamlText = env.YAML_TEXT;
})();

(async () => {
  const { yamlParse } = await import('@procedures/json');
  const text = globalThis.yamlText;
  if (typeof yamlParse !== 'function') throw new Error('@procedures/json: yamlParse is not a function');
  // The procedure expects the raw YAML string.
  const value = yamlParse(text);
  if (value === undefined) throw new Error('yamlParse returned undefined');
  globalThis.parsedValue = value;
})();

(async () => {
  const resultObj = { json: JSON.stringify(globalThis.parsedValue) };
  if (resultObj.json === undefined) throw new Error('Parsed JSON is undefined');
  console.log(JSON.stringify(resultObj));
})();
